pm.test("pokemon_id_shouldBe_between_1_and_1025_integer", function(){
    var jsonData = pm.response.json();

    pm.expect(jsonData.pokemon).to.have.property("id")
    pm.expect(Number.isInteger(jsonData.pokemon.id)).to.be.true
    pm.expect(jsonData.pokemon.id).to.be.at.least(1);
